  KEY `idx_idempotency_tenant_scene` (`tenant_id`,`scene`,`status`)
) ENGINE=InnoDB AUTO_INCREMENT=943 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='全系统幂等记录表';
