INSERT INTO `sys_config` VALUES (1,'主框架页-默认皮肤样式名称','sys.index.skinName','skin-blue','Y','admin','2026-06-01 16:53:29','',NULL,'蓝色 skin-blue、绿色 skin-green、紫色 skin-purple、红色 skin-red、黄色 skin-yellow',1),(2,'用户管理-账号初始密码','sys.user.initPassword','135246','Y','admin','2026-06-01 16:53:29','admin','2026-08-08 20:47:55','初始化密码 135246',1),(3,'主框架页-侧边栏主题','sys.index.sideTheme','theme-dark','Y','admin','2026-06-01 16:53:29','',NULL,'深色主题theme-dark，浅色主题theme-light',1),(4,'账号自助-是否开启用户注册功能','sys.account.registerUser','false','Y','admin','2026-06-01 16:53:29','',NULL,'是否开启注册用户功能（true开启，false关闭）',1),(5,'用户登录-黑名单列表','sys.login.blackIPList','','Y','admin','2026-06-01 16:53:29','',NULL,'设置登录IP黑名单限制，多个匹配项以;分隔，支持匹配（*通配、网段）',1),(6,'用户管理-初始密码修改策略','sys.account.initPasswordModify','1','Y','admin','2026-06-01 16:53:29','',NULL,'0：初始密码修改策略关闭，没有任何提示，1：提醒用户，如果未修改初始密码，则在登录时就会提醒修改密码对话框',1),(7,'用户管理-账号密码更新周期','sys.account.passwordValidateDays','0','Y','admin','2026-06-01 16:53:29','',NULL,'密码更新周期（填写数字，数据初始化值为0不限制，若修改必须为大于0小于365的正整数），如果超过这个周期登录系统时，则在登录时就会提醒修改密码对话框',1),(8,'用户管理-密码字符范围','sys.account.chrtype','0','Y','admin','2026-06-01 16:53:29','',NULL,'默认任意字符范围，0任意（密码可以输入任意字符），1数字（密码只能为0-9数字），2英文字母（密码只能为a-z和A-Z字母），3字母和数字（密码必须包含字母，数字）,4字母数字和特殊字符（目前支持的特殊字符包括：~!@#$%^&*()-=_+）',1),(100,'PC端单点登录','sys.login.singleLogin','true','Y','admin','2026-06-14 06:05:29','admin','2026-07-03 08:02:06','开启后同一账号PC端只允许一个在线，新登录踢掉旧登录',1),(101,'登录页禁止保存密码','sys.login.preventSavePassword','false','Y','admin','2026-06-14 06:05:29','admin','2026-08-03 10:46:29','开启后登录页清空浏览器自动填充的密码，阻止密码保存',1),(102,'登录验证码开关','sys.account.captchaEnabled','false','Y','admin','2026-06-14 06:05:29','wjs','2026-08-09 15:51:09','是否开启登录验证码（true开启/false关闭）',1),(103,'注册-身份证必填','sys.account.registerIdCardRequired','false','Y','system_backfill','2026-07-01 17:52:39','',NULL,'注册时是否必填身份证号（true必填 false选填）',1),(104,'注册-需要邀请码','sys.account.registerInviteCode','false','Y','system_backfill','2026-07-01 17:52:39','',NULL,'注册时是否需要邀请码（true需要 false不需要）',1),(105,'注册-新用户需审核','sys.account.registerNeedAudit','true','Y','system_backfill','2026-07-01 17:52:39','',NULL,'新注册用户是否需要管理员审核（true需要 false直接激活）',1),(106,'门店覆盖半径(米)','sys.dept.coverageRadius','1500','Y','system_backfill','2026-07-01 18:24:22','',NULL,'门店密度查询辐射半径，单位米，默认1500米(1.5公里)',1),(107,'高德地图API Key','sys.map.amapKey','354811df16ed437ed7787d2c4ecba142','Y','system_backfill','2026-07-01 18:24:22','',NULL,'高德Web服务API Key，用于地图选点逆地理编码（经纬度转详细地址）',1),(108,'财务库存-允许销售超库存出库','finance.stock.allowNegativeSaleOut','true','Y','admin','2026-07-02 16:39:39','codex','2026-07-02 16:39:39','true=允许销售出库后库存暂时为负，适用于先销售后进货发放；false=库存不足时阻断销售出库',1),(109,'R22企业微信群机器人启用','r22.touch.wework.enabled','false','N','admin','2026-07-04 22:00:55','system','2026-07-12 08:55:31','R22触达通道开关',1),(110,'R22企业微信群机器人DryRun','r22.touch.wework.dryRun','true','N','admin','2026-07-04 22:00:55','system','2026-07-12 08:55:31','DEV默认不真实发送',1),(111,'R22企业微信群机器人Webhook','r22.touch.wework.webhookUrl','','N','admin','2026-07-04 22:00:55','system','2026-07-12 08:55:31','真实环境由部署人员配置',1),(112,'R22触达单目标24小时上限','r22.touch.rateLimit.perTarget24h','3','N','admin','2026-07-04 22:00:55','system','2026-07-12 08:55:31','防刷屏',1),(113,'R23开放平台日额度开关','r23.openapi.dailyQuota.enabled','true','N','admin','2026-07-04 22:01:31','system','2026-07-12 08:55:31','R23 DEV 默认启用日额度校验',1),(114,'R23开放平台默认日额度','r23.openapi.dailyQuota.default','100','N','admin','2026-07-04 22:01:31','system','2026-07-12 08:55:31','未配置 Key 额度时的 DEV 默认额度',1),(115,'微信登录开关','mp.wechat.login.enabled','true','Y','system','2026-07-15 06:59:09','wjs','2026-07-31 01:39:39','小程序微信快捷登录入口开关。默认关闭(false)；各租户可在系统参数页面改为 true 启用。',1);
